import{c as r,Z as o,Q as n,j as s,m as l,o as t}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"如梦令·昨夜雨疏风骤","description":"","frontmatter":{"title":"如梦令·昨夜雨疏风骤","author":"李清照","dynasty":"宋"},"headers":[],"relativePath":"books/shici/songci/4.md","filePath":"books/shici/songci/4.md"}'),h={name:"books/shici/songci/4.md"};function u(c,a,p,d,q,_){const e=o("PoemAuthor"),i=o("PoemNav");return n(),s("div",null,[a[0]||(a[0]=l('<h1 id="如梦令·昨夜雨疏风骤" tabindex="-1">如梦令·昨夜雨疏风骤 <a class="header-anchor" href="#如梦令·昨夜雨疏风骤" aria-label="Permalink to &quot;如梦令·昨夜雨疏风骤&quot;">​</a></h1><p><strong>[宋] <a href="/authors/liqingzhao.html">李清照</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>昨夜雨疏风骤，浓睡不消残酒。试问卷帘人，却道海棠依旧。知否，知否？应是绿肥红瘦。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>雨疏风骤：雨点稀疏，风声急骤</li><li>浓睡：沉睡</li><li>残酒：残余的酒意</li><li>卷帘人：指侍女</li><li>绿肥红瘦：绿叶繁茂，红花凋零</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>昨夜雨点稀疏，风声急骤，我沉睡一夜，残余的酒意仍未消退。问卷帘的侍女，外面的海棠花怎么样了？她却回答说海棠花依旧和原来一样。知道吗？知道吗？应该是绿叶繁茂、红花凋零了。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首小令是李清照早期的代表作，以清新活泼的语言，描写了词人惜花伤春的情怀。</p><p>词的开头&quot;昨夜雨疏风骤&quot;，交代了背景，风雨交加的夜晚，让词人担忧院中的海棠花。&quot;浓睡不消残酒&quot;，写词人因惜花而饮酒，因饮酒而沉睡，但酒意未消，可见心事之重。</p><p>&quot;试问卷帘人&quot;，词人急切地询问花事，而侍女却漫不经心地回答&quot;海棠依旧&quot;。这一问一答，形成了鲜明的对比：词人细腻敏感，侍女粗疏淡漠。最后词人忍不住纠正道：&quot;知否，知否？应是绿肥红瘦。&quot;</p><p>&quot;绿肥红瘦&quot;四字，以拟人化的手法，形象地描绘出雨后花叶的变化，&quot;肥&quot;字写出绿叶的丰茂，&quot;瘦&quot;字写出红花的凋零，对比鲜明，生动传神。这四个字不仅是对自然景色的准确描摹，也暗含着词人对春光流逝的惋惜之情，以及对美好事物易逝的敏感与惆怅。</p><p>全词篇幅短小，却曲折有致，将惜花之情表达得委婉动人，体现了李清照早期词作清新婉丽的风格。</p>',14)),t(e,{name:"李清照",years:"1084年－约1155年",desc:"号易安居士，宋代著名女词人，婉约词派代表，有“千古第一才女”之称。其词前期多写悠闲生活，后期多悲叹身世。",link:"/authors/liqingzhao"}),t(i)])}const b=r(h,[["render",u]]);export{f as __pageData,b as default};
